public sealed record RegistrationLanguage(string Code, string DisplayName, string NativeDisplayName, RegistrationLanguageSupportTier Tier);
public enum RegistrationLanguageSupportTier { Tier1, Tier2 }

public static class RegistrationLanguageCatalog
{
