        new("bn-IN", "Bengali", "\u09ac\u09be\u0982\u09b2\u09be", RegistrationLanguageSupportTier.Tier2),
        new("mr-IN", "Marathi", "\u092e\u0930\u093e\u0920\u0940", RegistrationLanguageSupportTier.Tier2),
        new("ta-IN", "Tamil", "\u0ba4\u0bae\u0bbf\u0bb4\u0bcd", RegistrationLanguageSupportTier.Tier2),
        new("te-IN", "Telugu", "\u0c24\u0c46\u0c32\u0c41\u0c17\u0c41", RegistrationLanguageSupportTier.Tier2),
        new("kn-IN", "Kannada", "\u0c95\u0ca8\u0ccd\u0ca8\u0ca1", RegistrationLanguageSupportTier.Tier2),
        new("ml-IN", "Malayalam", "\u0d2e\u0d32\u0d2f\u0d3e\u0d33\u0d02", RegistrationLanguageSupportTier.Tier2),
        new("gu-IN", "Gujarati", "\u0a97\u0ac1\u0a9c\u0ab0\u0abe\u0aa4\u0ac0", RegistrationLanguageSupportTier.Tier2),
        new("pa-IN", "Punjabi", "\u0a2a\u0a70\u0a1c\u0abe\u0aac\u0a40", RegistrationLanguageSupportTier.Tier2),
        new("or-IN", "Odia", "\u0b13\u0b21\u0b3c\u0b3f\u0b06", RegistrationLanguageSupportTier.Tier2),
        new("as-IN", "Assamese", "\u0985\u09b8\u09ae\u09c0\u09af\u09bc\u09be", RegistrationLanguageSupportTier.Tier2)
