    public static string Get(string key, string? languageCode)
    {
        if (string.Equals(languageCode, "hi-IN", StringComparison.OrdinalIgnoreCase) && Hindi.TryGetValue(key, out var hindi)) return hindi;
        return English.TryGetValue(key, out var english) ? english : string.Empty;
    }
