    public static string GetReviewText(string value, string? languageCode) => string.Equals(languageCode, "hi-IN", StringComparison.OrdinalIgnoreCase) ? value switch { "Account" => "खाता", "Contact" => "संपर्क", "Marketplace" => "मार्केटप्लेस", "Provider" => "सेवा प्रदाता", "Seller" => "विक्रेता", "Business" => "व्यवसाय", "Location" => "स्थान", "Verification" => "सत्यापन", "Name" => "नाम", "Date of birth" => "जन्म तिथि", "Phone" => "फ़ोन", "Email" => "ईमेल", "Included access" => "शामिल सुविधाएं", "Commercial review" => "व्यावसायिक समीक्षा", "Provider type" => "प्रदाता प्रकार", "Category" => "श्रेणी", "Profession" => "पेशा", "Skills" => "कौशल", "Area" => "क्षेत्र", "Rate" => "दर", "Store" => "दुकान", "Product focus" => "उत्पाद प्रकार", "Pickup area" => "पिकअप क्षेत्र", "Trading name" => "व्यापारिक नाम", "Requested seats" => "अनुरोधित सीटें", "GSTIN" => "GSTIN", "Identity document" => "पहचान दस्तावेज़", _ => value } : value;
    public static string GetConflictPrompt(RegistrationConflict conflict, string? languageCode) => conflict.FieldKey switch { RegistrationQuestionKeys.PhoneNumber => Get("conflict.phone", languageCode), RegistrationQuestionKeys.Email => Get("conflict.email", languageCode), RegistrationQuestionKeys.DateOfBirth => Get("conflict.date", languageCode), RegistrationQuestionKeys.FirstName => Get("conflict.name", languageCode), _ => Get("conflict.choose", languageCode) };
    public static string LocalizeError(string? error, string? languageCode)
    {
        if (string.IsNullOrWhiteSpace(error)) return string.Empty;
        var key = error.Contains("phone", StringComparison.OrdinalIgnoreCase) ? "error.invalid-phone" : error.Contains("email", StringComparison.OrdinalIgnoreCase) ? "error.invalid-email" : error.Contains("birth", StringComparison.OrdinalIgnoreCase) || error.Contains("age", StringComparison.OrdinalIgnoreCase) ? "error.invalid-dob" : error.Contains("password", StringComparison.OrdinalIgnoreCase) ? "error.password" : null;
        return key is null ? error : Get(key, languageCode) is { Length: > 0 } localized ? localized : error;
    }
}
